/** A scenery piece (generated by `scripts/inventario-cenarios.mjs`). */
export type SceneryItem = {
  id: string;
  /** Pack the art comes from. */
  source: string;
  category: string;
  top: string;
  group: string;
  name: string;
  path: string;
  license: string;
  authors: string[];
  urls: string[];
  width: number;
  height: number;
  free: boolean;
  thumb: string | null;
};

const TREES = /^(trees_|treetop|trunk|plants_|flowers|wildflowers_|mushrooms)/i;
const BRIDGE_ETC = ['Bridges', 'Platforms', 'Pillars', 'Fences', 'Signs', 'Stairs', 'Misc'];
const isDoor = (item: SceneryItem): boolean => item.group.startsWith('Doors');

/**
 * Which lab page shows each piece. Each piece belongs to ONE page only:
 * the `cenarios-regras.test.ts` test checks that none was left without a page or on two.
 */
export const SCENERY_RULES: Record<string, (item: SceneryItem) => boolean> = {
  terrenos: (item) => item.category === 'terreno' && !TREES.test(item.name),
  plantas: (item) => item.category === 'terreno' && TREES.test(item.name),
  casas: (item) =>
    (item.top === 'Structure' &&
      ['Structures', 'Roofing', 'Walls', 'Wall Borders', 'Windows'].includes(item.group)) ||
    item.top === 'building-exterior',
  passagens: (item) =>
    (item.top === 'Structure' && (isDoor(item) || BRIDGE_ETC.includes(item.group))) ||
    item.top === 'sewer-dungeon',
  pisos: (item) =>
    (item.top === 'Structure' && item.group === 'Floor') || item.top === 'building-interior',
  mobilia: (item) =>
    item.category === 'objetos' &&
    (item.group.startsWith('Furniture') || item.group === 'Moveable' || item.top === 'object'),
  itens: (item) => item.category === 'objetos' && item.group.startsWith('Small Items'),
  parede: (item) => item.category === 'objetos' && item.group === 'Wall Items',
  efeitos: (item) => item.category === 'efeitos',
};
